import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# CUDA kernel for matrix multiplication (naive implementation)
cuda_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        int i = idx / N;
        int j = idx % N;
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[idx * K + k] * B[k * N + j];
        }
        C[idx] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b) {
    auto size_a = a.numel();
    auto out = torch::zeros_like(a);

    int M = a.size(0);
    int K = a.size(1);
    int N = b.size(1);

    const int block_size = 256;
    const int num_blocks = (M * N + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(a.data_ptr<float()>, b.data_ptr<float()>, out.data_ptr<float()>, M, K, N);

    return out;
}
"""

# cpp source declaration for the function
cpp_source = """
torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b);
"""

elementmat = load_inline(
    name="matmul",
    cpp_sources=cpp_source,
    cuda_sources=cuda_kernel_source,
    functions=["matmul_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul = elementmat

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul.matmul_cuda(A, B)
